'use strict';

const ENTER_KEY = 13;
const ESCAPE_KEY = 27;
const STORAGE_KEY = 'todos-vanillajs';

let todos = [];
let filter = '#/';
let editingId = null;

/**
 * Read the stored list.
 *
 * @planks("the app loads")
 * @planks("the browser has the stored todo {string}")
 * @planks("the browser has the stored todos {string}")
 * @planks("the browser has the stored completed todo {string}")
 * @returns {Array} the stored todos
 */
function load() {
	const raw = localStorage.getItem(STORAGE_KEY);
	return raw ? JSON.parse(raw) : [];
}

/**
 * Write the list to local storage.
 *
 * @planks("local storage under {string} holds one item titled {string} that is completed")
 * @planks("local storage under {string} holds one item titled {string} that is not completed")
 * @planks("no item in local storage under {string} carries an {string} field")
 * @planks("the value in local storage under {string} conforms to the {string} schema in {string}")
 */
function save() {
	localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
}

/**
 * Select the todos the current route shows.
 *
 * @planks("the user navigates to {string}")
 * @returns {Array} the visible todos
 */
function visible() {
	if (filter === '#/active') {
		return todos.filter((todo) => !todo.completed);
	}
	if (filter === '#/completed') {
		return todos.filter((todo) => todo.completed);
	}
	return todos;
}

/**
 * Draw the list, the counter, the filter links and the list furniture.
 *
 * @planks("the todo list holds the items {string}")
 * @planks("the todo list holds no items")
 * @planks("the todo {string} is completed")
 * @planks("the todo {string} is active")
 * @planks("the todos {string} are completed")
 * @planks("the todos {string} are active")
 * @planks("the todo {string} is in editing mode")
 * @planks("no todo is in editing mode")
 * @planks("the edit input of the todo {string} holds {string}")
 * @planks("the edit input of the todo {string} is the focused element")
 * @planks("the main section is hidden")
 * @planks("the main section is visible")
 * @planks("the footer is hidden")
 * @planks("the footer is visible")
 * @planks("the mark all as complete checkbox is checked")
 * @planks("the mark all as complete checkbox is unchecked")
 * @planks("the clear completed button is hidden")
 * @planks("the clear completed button is visible")
 * @planks("the counter reads {string}")
 * @planks("the strong element inside the counter reads {string}")
 * @planks("the filter link {string} is selected")
 * @planks("the filter link {string} is not selected")
 */
function render() {
	const list = document.querySelector('.todo-list');
	const active = todos.filter((todo) => !todo.completed);
	const completed = todos.length - active.length;

	list.innerHTML = '';
	for (const todo of visible()) {
		const item = document.createElement('li');
		item.dataset.id = todo.id;
		if (todo.completed) {
			item.classList.add('completed');
		}
		if (todo.id === editingId) {
			item.classList.add('editing');
		}

		const view = document.createElement('div');
		view.className = 'view';

		const toggle = document.createElement('input');
		toggle.className = 'toggle';
		toggle.type = 'checkbox';
		toggle.checked = todo.completed;

		const label = document.createElement('label');
		label.textContent = todo.title;

		const destroy = document.createElement('button');
		destroy.className = 'destroy';

		view.append(toggle, label, destroy);

		const edit = document.createElement('input');
		edit.className = 'edit';
		edit.value = todo.title;

		item.append(view, edit);
		list.append(item);

		if (todo.id === editingId) {
			edit.focus();
		}
	}

	const word = active.length === 1 ? 'item' : 'items';
	document.querySelector('.todo-count').innerHTML = `<strong>${active.length}</strong> ${word} left`;
	document.querySelector('.main').style.display = todos.length ? 'block' : 'none';
	document.querySelector('.footer').style.display = todos.length ? 'block' : 'none';
	document.querySelector('.clear-completed').style.display = completed ? 'block' : 'none';
	document.querySelector('.toggle-all').checked = todos.length > 0 && active.length === 0;

	for (const link of document.querySelectorAll('.filters a')) {
		link.classList.toggle('selected', link.getAttribute('href') === filter);
	}
}

/**
 * Find one todo by its identity.
 *
 * @param {string} id the todo identity
 * @planks("the user checks the todo {string}")
